<?php require_once dirname(__DIR__).'/lib.php';admin_required();$msg='';if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$c=cfg();$c['sms']['enabled']=isset($_POST['enabled']);foreach(['account','auth_key','sender','admin_phone'] as $k)$c['sms'][$k]=trim($_POST[$k]??'');$php="<?php\nreturn ".var_export($c,true).";\n";file_put_contents(dirname(__DIR__).'/config.php',$php);$msg='저장했습니다.';}catch(Throwable $e){$msg=$e->getMessage();}$s=cfg('sms');?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/app.css"><title>문자 설정</title></head><body><?php include '_top.php'?><main class="narrow"><h1>뿌리오 문자 설정</h1><?php if($msg):?><div class="alert warn"><?=e($msg)?></div><?php endif?><form method="post" class="card"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="checkline"><input type="checkbox" name="enabled" <?=$s['enabled']?'checked':''?>> 문자 발송 사용</label><label>계정<input name="account" value="<?=e($s['account'])?>"></label><label>인증키<input type="password" name="auth_key" value="<?=e($s['auth_key'])?>"></label><label>발신번호<input name="sender" value="<?=e($s['sender'])?>"></label><label>서명완료 알림번호<input name="admin_phone" value="<?=e($s['admin_phone'])?>"></label><br><button class="btn big">저장</button></form><div class="alert warn">임차인 서명 완료 시 임대인 연락처와 위 알림번호로 안내합니다. 최종 PDF 생성 후에는 임차인에게 PDF 다운로드 링크를 발송합니다. 발신번호는 뿌리오에 사전 등록된 번호를 입력하세요.</div></main></body></html>